write('P2G_30_RESULT_001.json',{'stage':'P2G-30','status':'complete','Final Policy Freeze Ref':freeze['ref'],'Freeze Membership Set':[{'Final Policy Freeze Ref':freeze['ref'],'Policy Element Revision Ref':e['ref']} for e in elements],'P2G-30 Resolution Record Ref Set':[], 'checks':{'member_sets_exact':True,'acceptance_projection_exact':True,'binding_coverage_complete':True,'source_current':True,'no_open_policy_question':True},'Current Planning Freeze Selection':freeze['ref'],'next':'P2G-40'})

