 {'id':'WP-CRSO-CORE','selectors':{'implementation':ids(4,6,7),'supporting':ids(3)},'boundary':'ValidatedGameData profile→catalog/plan→CoreApplication→BattleCore first spawn/restore/history/query','expected_change':'TD02/04: immutable generation admission identity; all expression consumers and bounded history routes; host profile restore','prerequisite':'WP-CRSO-CONFIG validated typed profile','validation':'V03–04,V06–07 isolated profiles, first spawn, nested rollback and history','unknown':'profile threading through existing fixture constructors; no meaning change permitted'},
 {'id':'WP-CRSO-PORTS','selectors':{'implementation':ids(5),'supporting':ids(4,6)},'boundary':'actual server bootstrap/actor/public command/result/snapshot/checkpoint/persistence rollback and author_content API/CLI','expected_change':'TD02/03 public application adapter with bound opaque transaction capability; CLI common profile option and receipts','prerequisite':'WP-CRSO-CORE generation/runtime profile contract; baseline server compiler errors','validation':'V04–06,V08 actual server and CLI/public API contract tests','unknown':'minimal opaque persistence transition API must preserve exact revision/session and monotonic profile'},
 {'id':'WP-CRSO-S1VERIFY','selectors':{'validation_only':ids(1,2,3,4,5,6,7,12)},'boundary':'S1 final public integration/current source regressions and immutable reversible audit target','expected_change':'durable V01–08,V12 integration fixtures and full verification; independent Astra High audit before S2','prerequisite':'three S1 implementation owners integrated','validation':'all required S1 conditions; exact source/input/lock/toolchain receipts; source restore forward/reverse; independent audit closure','unknown':'current PC/R05 measured costs remain actual results, not guessed thresholds'},
